from collections import deque
from math import sqrt

class Solution:

	def __init__(self):
		self.prime = [1 for i in range(10001)]
		self.prime[0] = 0
		self.prime[1] = 0
		for i in range(2, 10001):
			if self.prime[i] == 1:
				for j in range(i * 2, 10001, i):
					self.prime[j] = 0

	def convertIntToList(self, int_num):
		num_list = [0 for _ in range(4)]
		i = 3
		while i >= 0:
			num_list[i] = int_num % 10
			int_num //= 10
			i -= 1
		return list(num_list)

	def shortestPath(self, Num1, Num2):

		def dp(curr_num):
			if curr_num == Num2:
				return 0
			queue = deque([(curr_num, 0)])
			seen = {curr_num}
			while queue:
				(num, steps) = queue.popleft()
				num_list = self.convertIntToList(num)
				if num == Num2:
					self.ans = min(self.ans, steps)
				if steps < self.ans:
					for j in range(4):
						temp_num_list = list(num_list)
						for n in range(10):
							if n != num_list[j]:
								temp_num_list[j] = n
								num_list_int = int(''.join((str(x) for x in temp_num_list)))
								if num_list_int not in seen and self.prime[num_list_int] == 1 and (num_list_int >= 1000):
									seen.add(num_list_int)
									queue.append((num_list_int, steps + 1))
			return self.ans
		self.ans = float('inf')
		return dp(Num1)
